-- Backs the "agentProfiles" collection (type AgentProfile).
create table if not exists crm.agent_profiles (
  user_id                 text not null,
  org_id                  text not null,
  city                    text,
  pan                     text,
  id_proof_file_id        text,
  kyc_status              text, -- REJECTED | PENDING | VERIFIED
  kyc_note                text,
  specialization          text[],
  experience_years        numeric,
  sourcing_channels       text[],
  agreement_accepted_at   timestamptz,
  verified_by_name        text,
  verified_at             timestamptz,
  created_at              timestamptz,
  _extra                  jsonb not null default '{}'::jsonb, -- values that don't fit a typed column (kept losslessly)
  _position               double precision not null default 0, -- list order the app expects
  primary key (user_id)
);

-- Backs the "referrals" collection (type Referral).
create table if not exists crm.referrals (
  id                  text not null,
  org_id              text not null,
  agent_id            text,
  candidate_id        text,
  job_id              text,
  status              text, -- REJECTED | SUBMITTED | UNDER_REVIEW | SHORTLISTED | HIRED
  incentive_amount    numeric,
  incentive_paid      boolean,
  review_notes        text,
  resume_file_id      text,
  candidate_consent   boolean,
  agent_notes         text,
  created_at          timestamptz,
  updated_at          timestamptz,
  _extra              jsonb not null default '{}'::jsonb, -- values that don't fit a typed column (kept losslessly)
  _position           double precision not null default 0, -- list order the app expects
  primary key (id)
);

-- Backs the "referralMessages" collection (type ReferralMessage).
create table if not exists crm.referral_messages (
